input.sparql:
PREFIX brick: <http://brickdata.org/schema/>
SELECT ?s ?p ?o WHERE {
  ?s brick:hasLabel ?lbl .
  FILTER(CONTAINS(?lbl, "ZN_6"))
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?pt ?p ?o WHERE {
  ?pt rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl, "ZN_6"))
  OPTIONAL { ?pt ?p ?o }
}
LIMIT 200
